import subprocess, re, sys, hashlib

def funcs(path):
    out = subprocess.run(['objdump','-d','--no-show-raw-insn',path], capture_output=True, text=True).stdout
    res = {}
    cur = None; body = []
    for line in out.splitlines():
        if line.endswith('>:'):
            if cur is not None: res[cur] = body
            addr = int(line.split()[0],16)
            name = line.split('<')[1][:-2]
            cur = (addr, name); body = []
        elif cur is not None and line.startswith('  '):
            body.append(line.split('\t',1)[1].strip())
    if cur is not None: res[cur] = body
    return res

def norm(body):
    out=[]
    for b in body:
        b = b.split('#')[0].strip()
        b = re.sub(r'0x[0-9a-f]+','H',b)
        b = re.sub(r'\b[0-9a-f]+ <[^>]+>','A',b)
        out.append(b)
    return '\n'.join(out)

