fx = funcs('/out-fix/libarchive_fuzzer')
fx_by_name = {}
for (a,n),b in fx.items(): fx_by_name.setdefault(n, []).append(b)
print("vul funcs:", len(fv), "fix funcs:", len(fx), flush=True)
diffs = []
for (addr,name), body in fv.items():
    cand = fx_by_name.get(name)
    if not cand:
        diffs.append((name,'MISSING',addr,len(body))); continue
    nb = norm(body)
    if all(norm(c)!=nb for c in cand):
        diffs.append((name,'changed',addr,len(body)))
for d in sorted(diffs, key=lambda x:-x[3])[:60]: print(d)
print("total diffs:", len(diffs))
