    cur = []
    for line in out.splitlines():
        m = re.match(r'\s*([0-9a-f]+):\t(.*)', line)
        if not m: continue
        addr = int(m.group(1),16); ins = m.group(2).strip()
        if ins.startswith('endbr64') and cur:
            funcs.append(cur); cur=[]
        cur.append((addr, ins))
    if cur: funcs.append(cur)
    return funcs

def norm(f):
    out=[]
    for a,b in f:
        b = b.split('#')[0].strip()
        b = re.sub(r'0x[0-9a-f]+','H',b)
        b = re.sub(r'\b[0-9a-f]+ <[^>]+>','A',b)
        out.append(b)
    return out

