    for a,b in f:
        s=''
        if withstr and '#' in b:
            s = b.split('#',1)[1].strip()
        b = b.split('#')[0].strip()
        b = re.sub(r'0x[0-9a-f]+','H',b)
        b = re.sub(r'\b[0-9a-f]+ <[^>]+>','A',b)
        out.append(b+('|'+s if s else ''))
